def updates_ignored(items):
    if _ignored_sim:
        return _ignored_sim[0] == "\n".join(sorted(items))
    try:
        with open(IGNORED_UPDATES_FILE, encoding="utf-8") as fh:
            return fh.read(20000) == "\n".join(sorted(items))
    except OSError:
        return False


def updates_ignore(items):
    text = "\n".join(sorted(items))
    if SIMULATE:
        _ignored_sim[:] = [text]
        return
    os.makedirs(LOG_DIR, mode=0o700, exist_ok=True)
    with open(IGNORED_UPDATES_FILE + ".nuevo", "w", encoding="utf-8") as fh:
        fh.write(text)
    os.replace(IGNORED_UPDATES_FILE + ".nuevo", IGNORED_UPDATES_FILE)


# Menú lateral: sus apartados (clave, texto e icono) y cómo se ven (Apariencia: ~/.nexum/apariencia)
SIDEBAR = [("ENTORNO", [("proyectos", "Proyectos", "folder-symbolic"), ("repos", "Repositorios", "logo:github"),
                        ("versiones", "Versiones de PHP", "logo:php"), ("bbdd", "Bases de datos", "logo:bbdd"),
                        ("docker", "Docker", "logo:docker"), ("node", "Node", "logo:node")]),
           ("SISTEMA", [("dominios", "Dominios y hosts", "network-workgroup-symbolic"),
                        ("config", "Configuración", "emblem-system-symbolic")])]
# (siempre se ven: sin Configuración no se podrían volver a enseñar)
SIDEBAR_FIXED = ("proyectos", "config")
LOOK_FILE = os.path.join(LOG_DIR, "apariencia")
_look_sim = {}


def look_conf():
    """color (iconos en color), marcas (Docker, Node y PHP con su logotipo), ocultos (apartados que no se ven),
    zoom (el tamaño de la ventana, en %) y cristal (paneles translúcidos sobre un fondo de color)."""
    conf = dict(_look_sim)
    if not conf:
        try:
            with open(LOOK_FILE, encoding="utf-8") as fh:
                conf = json.loads(fh.read(4000))
        except (OSError, ValueError):
            conf = {}
    if not isinstance(conf, dict):
        conf = {}
    keys = {k for _g, items in SIDEBAR for k, _t, _i in items} - set(SIDEBAR_FIXED)
    hidden = conf.get("ocultos")
    return {"color": conf.get("color") is True, "marcas": conf.get("marcas") is True,
            "ocultos": {k for k in hidden if k in keys} if isinstance(hidden, list) else set(),
            "zoom": conf.get("zoom") if conf.get("zoom") in LOOK_ZOOMS else 100, "cristal": conf.get("cristal") is True}


# Tamaño de la ventana (Apariencia): en tanto por ciento
LOOK_ZOOMS = (80, 90, 100, 110)


def look_save(conf):
    data = {"color": conf["color"], "marcas": conf["marcas"], "ocultos": sorted(conf["ocultos"]),
            "zoom": conf.get("zoom", 100), "cristal": conf.get("cristal") is True}
    if SIMULATE:
        _look_sim.clear()
        _look_sim.update(data)
        return
    os.makedirs(LOG_DIR, mode=0o700, exist_ok=True)
    with open(LOOK_FILE + ".nuevo", "w", encoding="utf-8") as fh:
        json.dump(data, fh)
    os.replace(LOOK_FILE + ".nuevo", LOOK_FILE)


def css_zoom(text, zoom):
    """La hoja de estilos a otro tamaño: cada medida en px por zoom (las de 1 px, las rayas, se quedan igual).
    Las letras no van aquí: crecen o menguan con la resolución (gtk-xft-dpi), y con ellas las medidas en em."""
    if zoom == 100:
        return text

    def one(m):
        v = float(m.group(1))
        return m.group(0) if v <= 1 else "%gpx" % max(1, round(v * zoom / 100.0))
    return re.sub(r"(?<![\w.#-])(\d+(?:\.\d+)?)px", one, text)


GLASS_DIR = os.path.join(LOG_DIR, "cache", "cristal")


def glass_css():
    """El fondo del cristal: tres manchas difuminadas (azul, violeta y verde, los colores de Nexum) pintadas una
    sola vez en una imagen pequeña (~/.nexum/cache/cristal), que GTK estira a la ventana. Con degradados de CSS,
    GTK los volvía a calcular entero cada vez que se redibujaba algo (unos 28 ms; estirando la imagen, menos de 1)."""
    import cairo
    w, h = 256, 176
    out = []
    for name, sel, base, alpha in (("oscuro", "window.background.nv-cristal", (0.15, 0.16, 0.18), 1.0),
                                   ("claro", "window.background.nv-cristal.nv-claro", (0.95, 0.95, 0.96), 0.6)):
        path = os.path.join(GLASS_DIR, "fondo-%s.png" % name)
        if not os.path.isfile(path):
            try:
                os.makedirs(GLASS_DIR, mode=0o700, exist_ok=True)
                surf = cairo.ImageSurface(cairo.FORMAT_RGB24, w, h)
                cr = cairo.Context(surf)
                cr.set_source_rgb(*base)
                cr.paint()
                for cx, cy, r, rgb, a in ((0.08 * w, 0, 0.9, (0.11, 0.39, 0.93), 0.38),
                                          (w, h, 0.9, (0.49, 0.44, 0.85), 0.34),
                                          (0.62 * w, 0.3 * h, 0.6, (0.11, 0.61, 0.42), 0.16)):
                    g = cairo.RadialGradient(cx, cy, 0, cx, cy, r * max(w, h))
                    g.add_color_stop_rgba(0, rgb[0], rgb[1], rgb[2], a * alpha)
                    g.add_color_stop_rgba(1, rgb[0], rgb[1], rgb[2], 0)
                    cr.set_source(g)
                    cr.paint()
                surf.write_to_png(path + ".nuevo")
                os.replace(path + ".nuevo", path)
            except (OSError, MemoryError, cairo.Error):
                continue
        out.append('%s { background-color: rgb(%d, %d, %d); background-image: url("%s"); background-size: 100%% 100%%; }'
                   % (sel, base[0] * 255, base[1] * 255, base[2] * 255, GLib.filename_to_uri(path, None)))
    return "\n".join(out)


class MonoLogo(Gtk.DrawingArea):
    """Logotipo de un solo color, el del texto de donde va (como los iconos simbólicos del tema): en
    la barra lateral, igual que los demás iconos, también al elegir el apartado o cambiar de tema."""

    def __init__(self, name, size=16, colored=False):
        super().__init__()
        self.name, self.size, self.colored = name, size, colored
        w, h, _box = logo_frame(name, size)
        self.set_size_request(w, h)
        self.set_valign(Gtk.Align.CENTER)

    def do_draw(self, cr):
        c = self.get_style_context().get_color(self.get_state_flags())
        color = "#%02x%02x%02x" % (int(c.red * 255), int(c.green * 255), int(c.blue * 255))
        # (en color, el suyo; en la fila elegida, el del texto, que se lea sobre el azul)
        if self.colored and not row_selected(self):
            color, c = None, Gdk.RGBA(0, 0, 0, 1)
        scale = max(1, self.get_scale_factor())
        pix = logo_pixbuf(self.name, self.size, scale, color)
        cr.save()
        cr.scale(1.0 / scale, 1.0 / scale)
        Gdk.cairo_set_source_pixbuf(cr, pix, (self.get_allocated_width() * scale - pix.get_width()) / 2,
                                    (self.get_allocated_height() * scale - pix.get_height()) / 2)
        cr.paint_with_alpha(c.alpha)
        cr.restore()
        return False


def symbol(name, size=18):
    """Icono simbólico del tema (con otro de reserva si el tema no lo tiene)."""
    if not Gtk.IconTheme.get_default().has_icon(name):
        name = "applications-system-symbolic"
    return icon(name, size)


